import{_ as e,H as s,f as a,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"17-为什么前端页面里多选一个城市就报错？","description":"","frontmatter":{},"headers":[{"level":2,"title":"案例：为什么前端页面里多选一个城市就报错？","slug":"案例-为什么前端页面里多选一个城市就报错","link":"#案例-为什么前端页面里多选一个城市就报错","children":[]},{"level":2,"title":"开展排查","slug":"开展排查","link":"#开展排查","children":[{"level":3,"title":"确认和重现","slug":"确认和重现","link":"#确认和重现","children":[]},{"level":3,"title":"先做排除法","slug":"先做排除法","link":"#先做排除法","children":[]},{"level":3,"title":"tshark 命令","slug":"tshark-命令","link":"#tshark-命令","children":[]},{"level":3,"title":"HTTP 5xx 系列","slug":"http-5xx-系列","link":"#http-5xx-系列","children":[]},{"level":3,"title":"请求的映射","slug":"请求的映射","link":"#请求的映射","children":[]},{"level":3,"title":"根因分析","slug":"根因分析","link":"#根因分析","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"附录","slug":"附录","link":"#附录","children":[]}],"relativePath":"网络排查案例课/17-为什么前端页面里多选一个城市就报错？.md","filePath":"网络排查案例课/17-为什么前端页面里多选一个城市就报错？.md","lastUpdated":1795563497000}'),i={name:"网络排查案例课/17-为什么前端页面里多选一个城市就报错？.md"};function B(n,E,p,l,A,r){return s(),a("div",null,[...E[0]||(E[0]=[t(`<h1 id="_17-为什么前端页面里多选一个城市就报错" tabindex="-1">17-为什么前端页面里多选一个城市就报错？ <a class="header-anchor" href="#_17-为什么前端页面里多选一个城市就报错" aria-label="Permalink to &quot;17-为什么前端页面里多选一个城市就报错？&quot;">​</a></h1><p>你好，我是胜辉。</p><p>在第 15 讲中，我给你介绍了 Nginx 的 499 状态码的排查过程，这种排查方法其实也适用于其他 HTTP 状态码的排查。另外可能你也注意到了，这个案例是聚焦在后端 Web 日志方面的，那么如果遇到前端方面的报错，我们的排查又该如何开展呢？</p><p>所以今天这节课，我们就来探讨下这方面的排查技巧。跟往常一样，我们还是从案例说起。在这个过程中，你可以跟随我的脚步，通过抓包分析，把问题表象拆解为底层的数据流，然后深入到协议和应用的细节来找到根因。这样，以后你对类似的看起来凌乱没有头绪问题，也能有一套行之有效的方法来开展排查工作了。</p><h2 id="案例-为什么前端页面里多选一个城市就报错" tabindex="-1">案例：为什么前端页面里多选一个城市就报错？ <a class="header-anchor" href="#案例-为什么前端页面里多选一个城市就报错" aria-label="Permalink to &quot;案例：为什么前端页面里多选一个城市就报错？&quot;">​</a></h2><p>我们曾经服务过一家垂直 OTA（Online Travel Agency，在线旅游），他们专注于欧洲旅行市场，取得了不俗的业绩。有一天，客户的运维负责人找到我们，报告了一个奇怪的问题。</p><p>他们最近推出了一个旅游产品，可以让用户自主选择在欧洲旅行的多个城市之间，以自定义的顺序展开旅行。比如，你可以选择从西班牙的巴塞罗那启程，然后来到法国巴黎，随后踏上风车王国荷兰的领土，最后把日不落帝国的伦敦作为最后一站来结束旅行。以上旅程是由 4 个国家（城市）组成的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/1.png" alt=""></a></p><p>但是问题来了，如果你在网站上选择行程时多选一个地点，比如，中途增加一次到丹麦的旅程，使途经的国家 / 城市从 4 个变成 5 个，在提交旅行计划的时候，网站却会报错。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/2.png" alt=""></a></p><p>好像哪里有个环节跟公司作对似的，用户想多花点钱都不行？</p><h2 id="开展排查" tabindex="-1">开展排查 <a class="header-anchor" href="#开展排查" aria-label="Permalink to &quot;开展排查&quot;">​</a></h2><p>我们先来看一下整体的架构，他们这个还是比较典型的 Web 应用的基础架构：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/3.png" alt=""></a></p><p>云 LB 是基于 HAProxy 方案的软件负载均衡产品，它分发流量给后端的云主机 Nginx，上面运行着 Web 程序，再后面就是云数据库了。</p><h3 id="确认和重现" tabindex="-1">确认和重现 <a class="header-anchor" href="#确认和重现" aria-label="Permalink to &quot;确认和重现&quot;">​</a></h3><p>问题排查的第一步是什么？</p><p>一般来说，是问题的准确描述和重现。就是说，如果问题不是你自己发现而是其他人报告给你的，那么你需要确认对方描述的每一个事实细节。我们按照客户描述的顺序，登录网站后依次选择了 5 个城市，在提交行程的时候果然遇到报错了。而改为只选择 4 个城市，就能提交成功。</p><p>问题可以重现，第一步完成。</p><h3 id="先做排除法" tabindex="-1">先做排除法 <a class="header-anchor" href="#先做排除法" aria-label="Permalink to &quot;先做排除法&quot;">​</a></h3><p>问题排查的第二步是什么？</p><p>一般来说，是可以做排除法筛选问题根因。这跟我们考试做选择题的时候类似，如果你在 A、B、C、D 四个选项中无法一下子就找到正确选项，那可以先排除那些明显错误的选项，最后剩下的就是答案了。</p><p>我们让客户自查了云数据库、云主机应用服务器，都没有发现问题。而且客户报告，如果绕过云 LB，直接访问云主机 Nginx 或者云主机应用服务器，同样的方式预订 5 个城市的旅程，都能提交成功。访问外部站点（经过云 LB），就会提交失败。所以我们再对比一下：</p><ul><li><p>失败场景：公网用户 -&gt; 云 LB -&gt; 云主机 Nginx</p></li><li><p>成功场景：内网用户 --------&gt; 云主机 Nginx</p></li></ul><p>这样看起来，问题就集中到云 LB 上了。</p><p>于是我们在云 LB 上开始排查，当然这里少不了用 tcpdump 做抓包。对于云 LB 来说，对同一个应用请求，它其实需要处理两个 TCP 连接。</p><ul><li><p>客户侧连接：公网客户 IP &lt;-&gt; 云 LB 弹性 IP。</p></li><li><p>服务侧连接：云 LB 内部 IP &lt;-&gt; 云主机 Nginx 内部 IP。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/4.png" alt=""></a></p><p>于是我们把这两段不同的 TCP 连接也都抓取了。好在这个问题是必现的，我们只要选择那五个城市，问题就必然出现，所以很容易就抓取到了问题报文。先预告一下，在后面的课程中，我还会提到对于偶发性问题的排查思路，它跟必现型问题的排查确实有挺大的不同。</p><h3 id="tshark-命令" tabindex="-1">tshark 命令 <a class="header-anchor" href="#tshark-命令" aria-label="Permalink to &quot;tshark 命令&quot;">​</a></h3><p>我们先看一下客户侧抓包的情况。因为是 HTTP 应用，我们可以重点关注其 HTTP 返回码的情况。这里，我们要学习一个新的强大的命令行工具：tshark。</p><p>在安装 Wireshark 软件包的时候，它默认也会连带安装其他几个强大的命令行工具，比如capinfos、tshark、dumpcap、editcap、mergecap 等。这里的 tshark 事实上可以起到类似tcpdump 的作用，比如在我使用的 macOS 笔记本上，用 Wireshark、tcpdump、dumpcap，还有 tshark，都可以抓包。</p><p>当然，tshark 也可以读取和解析抓包文件。关于 tshark 的更多说明，可以参考官方文档。</p><p>你可能会问：“既然 tshark 跟 tcpdump 差不多，为什么一定要用 tshark 呢？”</p><p>这是因为，tshark 解读文件时，可以像 Wireshark 那样解读到应用层，而这一点，tcpdump 就无法做到了。在当前这个案例里，我们需要用上 tshark 的报文分析功能，过滤并统计 HTTP返回码的分布情况。命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ tshark -r lesson17-in.pcap -T fields -e http.response.code | grep -v ^$ | sort</span></span>
<span class="line"><span>2883 200</span></span>
<span class="line"><span>704 502</span></span>
<span class="line"><span>227 304</span></span>
<span class="line"><span>141 400</span></span>
<span class="line"><span>45 301</span></span>
<span class="line"><span>41 302</span></span>
<span class="line"><span>16 408</span></span>
<span class="line"><span>13 403</span></span>
<span class="line"><span>6 503</span></span>
<span class="line"><span>6 404</span></span>
<span class="line"><span>2 206</span></span></code></pre></div><ul><li>补充：抓包示例文件已经上传至Gitee，建议结合文稿和 Wiresahrk、tshark 一起学习。</li></ul><p>可以看到，返回码 200 的情况还是占了绝大多数（2883 个），其次是返回码 502（704 个），然后余下的是的 3xx 系列和 4xx 系列的返回码，还有 6 个 503 返回码。</p><p>当然，你用 Wireshark 图形界面也很容易获得这种信息。在 Wireshark 的 Statistics 下拉菜单里，选择 HTTP -&gt; Packet Counter：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/5.png" alt=""></a></p><p>然后就能看到统计信息了。可见，这些数据跟我们用 tshark 命令行工具做解析的数字是一致的：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/6.png" alt=""></a></p><p>可能你要问了，显然图形界面更加方便一点，tshark 工具的价值又在哪里呢？这里我来说说我的看法吧。</p><ul><li><p>当我们需要分享抓包分析信息给其他人的时候，tshark 的输出信息是文本格式，就很方便分享了。而 Wireshark 的是截图，就没有文本那么方便。</p></li><li><p>当我们有多个文件需要做同一种分析的时候，tshark 命令行工具优势就体现出来了，因为不需要打开多个 Wireshark 窗口，而是在同一个命令行窗口里就可以对多个抓包文件依次执行相似的命令，然后对比这些输出，十分方便。</p></li><li><p>当我们要对抓包分析进行自动化的时候，tshark 这样的命令行工具以及类似的开发库就很有用了，可以帮助我们把人的经验沉淀到代码里去，减少人工的工作量。</p></li></ul><h3 id="http-5xx-系列" tabindex="-1">HTTP 5xx 系列 <a class="header-anchor" href="#http-5xx-系列" aria-label="Permalink to &quot;HTTP 5xx 系列&quot;">​</a></h3><p>回到这个案例。这么多 502/503 的返回码确实不太正常，这又跟 502/503 本身的语义有关。我们分别来看一下协议中定义的502、503和504。</p><p>在学习 HTTP 协议的时候，除了阅读 RFC2616 等 RFC 文档，还可以参考 MDN（MozillaDeveloper Network），因为是有中文版的，所以对我们更加友好。这里，我们就用它的中文解释：</p><p>502 Bad Gateway - HTTP | MDN (mozilla.org)：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>502 Bad Gateway 是一种HTTP协议的服务器端错误状态代码，它表示作为网关或代理角色的服务器，从上游</span></span></code></pre></div><p>503 Service Unavailable - HTTP | MDN (mozilla.org)：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>503 Service Unavailable 是一种HTTP协议的服务器端错误状态代码，它表示服务器尚未处于可以接受请</span></span></code></pre></div><p>504 Gateway Timeout - HTTP | MDN (mozilla.org)：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>504 Gateway Timeout 是一种HTTP协议的服务器端错误状态代码，表示扮演网关或者代理的服务器无法在规</span></span></code></pre></div><p>你可能也看出来了，502/503/504 这几个返回码，都是给 反向代理 / LB 用的。反向代理 / LB位于客户和服务之间，起到了转发、分流、处理的作用。这里我稍微再给你展开一下这几类功能。</p><ul><li>转发</li></ul><p>这个最基础最直观，就是把客户发过来的请求，转发给后端服务器。因为一般来说反向代理跟</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>后端服务器是 1:n 的关系，所以需要用一些算法来进行分发，来保证后端分到的请求数量是</span></span></code></pre></div><p>符合预期的。常见的算法有轮询、权重、最小连接数、哈希等等。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/7.png" alt=""></a></p><ul><li>路由分流</li></ul><p>这是第七层的路由分发，把符合一定条件的 HTTP 请求分发到路由配置的对应的后端集群，可以说是带条件判断的转发。搜索引擎优化（Search Engine Optimization，简称 SEO）就是一个典型的例子，它把各种子域名集中到主站域名下面，比如：</p><ul><li><p>register.abc.com 转为 www.abc.com/register（注册）</p></li><li><p>cart.abc.com 转为 www.abc.com/cart（购物车）</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/8.png" alt=""></a></p><p>这样的话，多个子域名就统一为单一域名 www.abc.com，原本分散到各个子域名的搜索得分也被合并了，一下子提升了主站的排名。</p><ul><li>处理</li></ul><p>这里是指应用层的业务处理。这个会比较多样，比如可能直接由反向代理回复给客户一个301/302 http redirect，也可能改写 URL 后转发给后端进一步处理，等等，总之是应用层的行为。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/9.png" alt=""></a></p><p>好，我们继续 502/503/504 的话题。因为反向代理 / LB 是位于客户和服务之间的，如果服务坏了，而反向代理 / LB 本身没坏，那么该给客户回复哪个返回码呢？500 吗？可是服务端故障，但我反向代理 / LB 自己可没故障啊。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/10.png" alt=""></a></p><p>为了“撇清”这层关系，反向代理 / LB 可以用 502/503/504 这些返回码向客户端表明清白之身：我自己没问题，是我后面的服务出了问题。所以说，遇到大量 502/503/504 时，你应该重点查一下产生这些返回码的背后的原因。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/11.png" alt=""></a></p><p>我们从抓包文件里基于测试机的外网 IP，过滤出了问题重现时发生的 HTTP 事务，做下一步</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>的分析。输入过滤条件：ip.addr == x.x.x.x（此处隐去了真实 IP），然后过滤到这个测</span></span></code></pre></div><p>试引发的数据包：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/12.png" alt=""></a></p><ul><li>补充：HTTP 502 的示例文件已经上传至Gitee。</li></ul><p>其中，赫然出现 HTTP 502。接下来你也知道，我们需要对这个 TCP 流进行重点分析。选中HTTP 502 这个包，右单击 Follow，在弹出子菜单中选中 TCP stream。此时会有弹出窗口，里面展示了 HTTP 应用层面的信息，即 HTTP 请求和对应的 HTTP 返回。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/13.png" alt=""></a></p><ul><li>补充： 由于我们可以想到的原因，这里把敏感信息抹去了。</li></ul><p>一个 POST 请求，得到了 HTTP 502，这并不正常，会不会跟这个奇怪的前端问题有关系呢？由于这只是客户侧的情况，我们必须跑到云 LB 的另外一侧即服务侧，看看那边发生了什么。分析那边的数据包，也许就能定位到 502 产生的原因了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/14.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/14.png" alt=""></a></p><h3 id="请求的映射" tabindex="-1">请求的映射 <a class="header-anchor" href="#请求的映射" aria-label="Permalink to &quot;请求的映射&quot;">​</a></h3><p>云 LB 的左边是一个 TCP 连接，右边是另外一个 TCP 连接，两者在网络层面毫无关联。只有云 LB 自己知道，左边连接里的某个 HTTP 事务，对应的是右边连接的哪个 HTTP 事务。那么，如何根据客户侧的数据，找到对应的服务侧的数据呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这也是一个不小的挑战。这个问题的抽象描述，就是：如何在一个 m:n 的场景里，找到确定</span></span>
<span class="line"><span>的 1:1 关系。下图中，我用虚线表示了这种映射关系的未知性。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/15.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/15.png" alt=""></a></p><p>相信这个问题的答案不止一种。这里我想分享给你的经验是，利用 Wireshark 提供的一个过滤器：tcp contains。</p><p>使用这个方法的根据是：进入到客户侧的请求，一般会由 LB 或反向代理大体不改动地转发到服务侧。这里说“大体不改动”，是因为反向代理或者 LB 可能会插入一些 HTTP header（比如常见的 X-Forwarded-For），但一般不改写原有的 URL 和 header。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/16.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/16.png" alt=""></a></p><ul><li>补充：除了这个方法以外，一些商业 LB 会提供更为强大的 TCP 流映射抓包功能，就是在指定抓取某个客户端 IP 的流量的同时，还能实时把对应的服务侧连接的数据包都抓取到。当然，在这个案例里并不是非要这种强大功能不可，用我刚介绍的过滤器也可以做到。</li></ul><p>首先，回到我们客户侧的数据包，找到一个容易区分该 HTTP 请求跟其他 HTTP 请求的标志。比如应用层时常会用 uuid，作为区分不同 HTTP 请求的方法，正好可以为我们所用。我们看一下这个 HTTP 请求，看来“sk=xxx”这个 uuid 比较适合作为过滤条件，也就是图中圈出来的部分，它在不同的请求间重复的可能性为零。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/17.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/17.png" alt=""></a></p><p>然后，用 Wireshark 打开服务侧抓包文件，在过滤器输入框中输入下面的条件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp contains &quot;eucir_e3fb2a65b12c36bfbde7aa0a6e6f0041&quot;</span></span></code></pre></div><p>这样就能过滤出相关的服务侧的数据包，而这些报文就是对应了客户侧的同一个请求：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/18.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/18.png" alt=""></a></p><p>Wireshark 提示我们，这些报文都是 TCP segment of a reassembled PDU，也就是属于同一个大的应用层数据的不同数据段。我们选中其中一个报文并右键 Follow -&gt; TCP stream，得到这个 TCP 连接的完整数据：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/19.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/19.png" alt=""></a></p><p>HTTP 请求是红色字体，HTTP 响应是蓝色字体。你注意下这个 HTTP 响应，是否发现了不同寻常的事情？</p><p>原来，在服务侧这个 HTTP 请求得到的不是 502，而是正常的 200！</p><p>让我们更多地解读一下这个 200 返回带给我们的信息：</p><ul><li>请求中的 sk=xxx 跟客户侧的请求的 sk=xxx 值一致，也就是我们可以确认：该服务侧请求即客户侧请求。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>该返回的头部（header）包含 Server: nginx，由此得知，云 LB 后面的这个 Server 是</span></span></code></pre></div><ul><li><p>Nginx。</p></li><li><p>返回的头部信息也比较大，有很多个 Set-Cookie。</p></li></ul><p>那么排查到这里，我们就可以大致拼接出来问题的全貌了：</p><ul><li><p>公网客户访问云 LB，得到 HTTP 502；</p></li><li><p>云 LB 访问后端云主机，得到 HTTP 200。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/20.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/20.png" alt=""></a></p><p>于是，整个排查过程有了非常重要的进展。只要能回答“是什么原因让云 LB 把 HTTP 200 变成 HTTP 502”这个问题，整件事情就算水落石出了。</p><h3 id="根因分析" tabindex="-1">根因分析 <a class="header-anchor" href="#根因分析" aria-label="Permalink to &quot;根因分析&quot;">​</a></h3><p>在揭示真相之前，让我们再次回到 HTTP 502 的语义本身，看看我们在说 502 的时候，我们说的到底是什么。这是 RFC2616 中针对502 Bad Gateway所给出的定义：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>502 Bad Gateway</span></span>
<span class="line"><span>  The server, while acting as a gateway or proxy, received an invalid</span></span>
<span class="line"><span>  response from the upstream server it accessed in attempting to</span></span>
<span class="line"><span>  fulfill the request.</span></span></code></pre></div><ul><li>作为网关或者代理的服务器，在试图从它的上游服务器（后端服务器）执行 HTTP 请求时，接收到了一个无效的响应。</li></ul><p>所以，云 LB（基于 HAProxy）认为，后端返回的 HTTP 响应并不符合它对于“有效”的定义。但是，显然后端回复的 HTTP 200 怎么看都是正常的、标准的，那 HAProxy 又有什么理由认为其无效呢？如果协议标准定义里面没有这个答案，那么只可能在 HAProxy 自己的定义 / 配置里面找寻答案了。</p><p>我们以“HAproxy HTTP 502”为条件进行搜索，发现有多种情况会导致 HAProxy 回复 502 给客户端，比如：</p><ul><li><p>后端服务器返回的 HTTP 响应不符合 HTTP 规范；</p></li><li><p>后端服务器没有及时响应；</p></li><li><p>header 的大小写问题；</p></li><li><p>header size 超限。</p></li></ul><p>考虑到客户在内网直接测试 Nginx 可以正常完成，那么 1、2、3 基本可以排除。header size要重点排查，因为你也可以看到在 Wireshark 中，HTTP 响应（蓝色字体）的 header 部分比较大，比如有好几个大尺寸的 Set-Cookie 头部，在 Wireshark 应用层信息窗口里翻好几页才能看完。</p><p>为了获取最权威的解释，我查阅了 HAProxy 版本 1.5.0 的官方文档，并对比了 v1.5.0 的源代码，终于发现了 header size 的秘密。</p><p>关键代码就在 include/common/defaults.h 文件中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*</span></span>
<span class="line"><span>* BUFSIZE defines the size of a read and write buffer. It is the maximum</span></span>
<span class="line"><span>* amount of bytes which can be stored by the proxy for each session. However,</span></span>
<span class="line"><span>* when reading HTTP headers, the proxy needs some spare space to add or rewrite</span></span>
<span class="line"><span>* headers if needed. The size of this spare is defined with MAXREWRITE. So it</span></span>
<span class="line"><span>* is not possible to process headers longer than BUFSIZE-MAXREWRITE bytes. By</span></span>
<span class="line"><span>* default, BUFSIZE=16384 bytes and MAXREWRITE=BUFSIZE/2, so the maximum length</span></span>
<span class="line"><span>* of headers accepted is 8192 bytes, which is in line with Apache&#39;s limits.</span></span>
<span class="line"><span>*/</span></span>
<span class="line"><span>#ifndef BUFSIZE</span></span>
<span class="line"><span>#define BUFSIZE         16384</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>// reserved buffer space for header rewriting</span></span>
<span class="line"><span>#ifndef MAXREWRITE</span></span>
<span class="line"><span>#define MAXREWRITE      (BUFSIZE / 2)</span></span></code></pre></div><p>也就是说：</p><ul><li><p>HAProxy 定义了一个读写缓存 BUFSIZE。</p></li><li><p>每次读取 HTTP 头部的时候，有可能会做增加 header 和改写 header 的操作，所以预留了一部分空间 MAXREWRITE，它的值等于 BUFSIZE/2。</p></li><li><p>真正可以用来临时存放 HTTP 头部的缓存大小就是：BUFSIZE - MAXREWRITE = 16384 -16384/2 = 8192 字节。 也就是真正能接纳的 HTTP 请求的头部的大小，只有 8192 字节！</p></li></ul><p>那么接下来，我们就来验证下 header size 是否真的超出了 8KB。</p><p>依然是在 Wireshark 界面里，我们再次审视服务侧的请求和响应数据包，计算一下整体的header size。我们用这样一个过滤器，让展示出来的报文信息便于我们做统计：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tcp.stream eq 0 and tcp.srcport eq 80</span></span></code></pre></div><p>这样的话，这次 TCP 流里的从后端服务器（源端口 80）发回的数据量就清晰可见了：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/21.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/21.png" alt=""></a></p><p>上图中的红框部分，就是后端云主机 Nginx 返回的 HTTP 响应的大小。这里，又分别有两种方法来获得这个数值：</p><ul><li><p>把 TCP Seglen 列的数字求和；</p></li><li><p>直接用最后一个报文（24 号报文）的 nextSeq-1。</p></li><li><p>注意：减去的 1 是握手阶段的 1。</p></li></ul><p>用任何一种方法，算出来的都是 10791 字节。不过先别急，这是整个 HTTP 响应的大小，并不是 HTTP headers 的大小。我们还要减去 HTTP body，这个 body 的大小要怎么获取呢？</p><p>你应该还记得在上节课里，我们学习过 HTTP 协议头部的构造，其中 Content-Length 头部就是表示了 HTTP body 的大小。那么在这里我们就可以利用这个属性：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/22.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/17-%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%2589%258D%25E7%25AB%25AF%25E9%25A1%25B5%25E9%259D%25A2%25E9%2587%258C%25E5%25A4%259A%25E9%2580%2589%25E4%25B8%2580%25E4%25B8%25AA%25E5%259F%258E%25E5%25B8%2582%25E5%25B0%25B1%25E6%258A%25A5%25E9%2594%2599%25EF%25BC%259F/22.png" alt=""></a></p><p>可见，HTTP body 的大小就是 940 字节。我们做个减法：10791- 940 = 9851</p><p>再去掉 HTTP headers 和 body 的分隔符即两个 CRLF，它们是 4 个字节，那么最终得到HTTP headers 的大小是：9851 - 4 = 9847</p><p>显然 9847 超过了 8192。根因已经一目了然了：HTTP Respose header 部分的大小超过了默认限制的 8KB！</p><p>这个原因也很好地解释了为什么选 5 个城市就会失败，而 4 个城市就能成功，因为前者生成的 HTTP 请求头部超过了 8192 字节，而后者正好没超。</p><p>后来的故事就比较简单了，我们做了两件事：</p><ul><li><p>临时修改了云 LB（HAProxy）的配置，把它的限制从 8KB 提升到 16KB，这个问题立刻被解决了。</p></li><li><p>作为长期方案，我们建议客户合理使用 Set-Cookie 头部，确保整体的 HTTP Responsesize 在一定的合理区间之内（8KB），避免无谓的系统开销和难以预料的问题的发生。</p></li></ul><p>这样，客户的客户终于可以开开心心地去旅游玩耍，想去几个城市就去几个城市了。</p><p>我最后再简单回顾一下整个排查过程，希望对你有所启发：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-&gt; 确认问题症状</span></span>
<span class="line"><span>-&gt; 排除法确定问题在LB</span></span>
<span class="line"><span>-&gt; tshark统计发现大量502</span></span>
<span class="line"><span>-&gt; 根据前端连接的应用层uuid，找到后端连接的对应TCP流</span></span>
<span class="line"><span>-&gt; 发现后端连接实际返回200，定位是HAProxy导致</span></span>
<span class="line"><span>-&gt; 从文档和源码中确认是header size的限制</span></span>
<span class="line"><span>-&gt; 计算抓包文件中字节数，确认根因是超限</span></span>
<span class="line"><span>-&gt; 提升header size limit，问题解决</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课，我通过一个比较有趣的问题的排查过程，带你了解并学习了以下这些知识点，你需要重点掌握好。</p><ul><li>HTTP 502/503/504 状态码的本质</li></ul><p>HTTP 5xx 系列状态码的语义的本质：跟 500 不同，502、503、504 都是 LB / 反向代理的后端的服务出了问题。基于这些理解，下一次你再遇到 5xx 的问题，相信就已经有比较充足的知识储备，能判断出是 Web 服务器本身有问题，还是反向代理 / LB 有问题了。</p><ul><li>两侧不同 TCP 连接的映射</li></ul><p>在排查 LB / 反向代理的问题的时候，经常遇到一个重大的挑战：在左右两侧的不同 TCP 连接中，找到同一个应用层事务。这次我给你介绍了用应用层的 uuid 作为映射线索的方法。先在</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一侧的抓包文件中选定一个 uuid，然后在另一侧的抓包文件中使用 tcp contains &quot;uuid&quot;</span></span></code></pre></div><p>这样一个过滤器，找到对应这同一个应用层事务的另一侧的报文。</p><p>在第 5 讲中，我也介绍过另外一种类似的找到对应报文的方法。但是注意，你不要把它们混淆起来了，其实这两个方法本质上是不同的，因为它们的场景完全不同。</p><p>这节课的场景是，客户端请求发给 LB，LB 转发请求给服务端，这是两个完全不同的 TCP 连接，只是因为是属于同一个应用层事务，所以同样的应用层数据（比如 uuid）在两侧抓包中都有体现。</p><p>第 5 讲的场景是，客户端和服务端对同样的连接做了抓包，这两个抓包文件里的报文都是属于同一个 TCP 连接的，所以同样的传输层信息（比如序列号）在两端抓包中都有体现。</p><ul><li>结合产品文档和代码查找根因</li></ul><p>然后，我还给你介绍了如何结合程序文档（有时候要阅读源代码）和抓包分析中观察到的现象，彻底定位问题根因的方法。</p><p>在这个案例中，我们查看源码，发现了 header size 方面的限制，然后对抓包文件中的报文进行仔细的核对，终于证实了这个推断。你也可以借鉴这种思路，在遇到跟数据长度限制之类的的问题的时候，来完成类似的推理验证。</p><ul><li>tshark 工具</li></ul><p>在工具方面，这节课我们也学习了一个新的强大工具：tshark。用 tshark，我们可以方便的在命令行中就实现 Wireshark 图形界面中能做的各种过滤操作，对于快速排查问题、统计各种指标，都非常有帮助。比如用这条命令可以查看 HTTP 返回码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tshark -r file.pcap -T fields -e http.response.code</span></span></code></pre></div><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后，给你留两道思考题：</p><ul><li><p>如果 LB / 反向代理给客户端回复 HTTP 503，表示什么呢？如果 LB / 反向代理给客户端回复 HTTP 500，又表示什么呢？</p></li><li><p>这节课里，我介绍了使用应用层的某些特殊信息，比如 uuid 来找到 LB 两侧的报文的对应关系。你有没有别的好方法也可以做到这一点呢？</p></li></ul><p>欢迎在留言区分享你的答案，也欢迎你把今天的内容分享给更多的朋友。</p><h2 id="附录" tabindex="-1">附录 <a class="header-anchor" href="#附录" aria-label="Permalink to &quot;附录&quot;">​</a></h2><p>示例文件已经上传至Gitee，建议结合文稿和 Wireshark、tshark 打开示例文件一起学习。</p>`,162)])])}const c=e(i,[["render",B]]);export{h as __pageData,c as default};
